<?php
declare(strict_types=1);
function prepared_data():array { $p=EP_ROOT.'/private/prepared-data-v24.json';if(!is_file($p)){$p=EP_ROOT.'/private/prepared-data-v25.json';if(!is_file($p))fail('ملف البيانات المجهزة غير موجود.');}return decode(file_get_contents($p)); }
function setup_profile(array $r):array{return ['setup_serial'=>(int)$r['A'],'name_en'=>$r['C']??'','civil_id'=>$r['D']??'','nationality'=>$r['E']??'','phone'=>$r['F']??'','email'=>$r['G']??'','note'=>$r['H']??''];}
function setup_plan(array $doc):array {
 $companies=query('SELECT * FROM ep_companies')->fetchAll();$users=query('SELECT * FROM ep_users')->fetchAll();$out=[];$errors=[];$serials=[];$civil=[];
 foreach($doc['companies']as $r){if(empty($r['B'])||empty($r['A'])){$errors[]='شركة بدون اسم أو مسلسل';continue;}$found=array_values(array_filter($companies,fn($c)=>$c['name']===$r['B']));if(count($found)>1)$errors[]='اسم شركة مكرر على الموقع: '.$r['B'];$out[]=['kind'=>'company','serial'=>$r['A'],'name'=>$r['B'],'code'=>$found[0]['code']??'تلقائي','existing_id'=>$found[0]['id']??null];}
 foreach($doc['people']as $r){$serial=(int)$r['A'];if($serial<1||isset($serials[$serial]))$errors[]='مسلسل موظف مكرر أو غير صالح';$serials[$serial]=true;if(!empty($r['D'])){if(isset($civil[$r['D']]))$errors[]='رقم مدني مكرر داخل الملف';$civil[$r['D']]=true;}$found=[];foreach($users as $u){$p=decode($u['profile_json']);if(($p['setup_serial']??null)===$serial||(!empty($r['D'])&&($p['civil_id']??'')===$r['D']))$found[]=$u;}
 if(count($found)>1)$errors[]='هوية مكررة للموظف '.$serial;
 if(!$found)foreach($users as $u)if($u['name']===$r['B'])$errors[]='الاسم موجود؛ طابق المدنية قبل الاستيراد: '.$r['B'];
 if($found&&$found[0]['name']!==$r['B'])$errors[]='تعارض اسم وهوية الموظف '.$serial;
 $out[]=['kind'=>'employee','serial'=>$serial,'name'=>$r['B'],'code'=>$found?employee_key($found[0]):'تلقائي','existing_id'=>$found[0]['id']??null];}
 $dates=[];foreach($doc['periods']as $r){try{$from=import_date($r['C']??'');$to=empty($r['D'])?null:import_date($r['D']);$person=current(array_filter($doc['people'],fn($p)=>(int)$p['A']===(int)$r['A']));if(!$person||$person['B']!==$r['B'])throw new RuntimeException('اسم الفترة لا يطابق الموظف');if(!$from||($to&&$to<$from)||!isset($serials[(int)$r['A']]))throw new RuntimeException('تواريخ أو مسلسل غير صالح');if(!in_array($r['I']??'', ['شريك','مكتب','مندوب','عن بُعد'],true)||!in_array($r['J']??'', ['نعم','لا'],true))throw new RuntimeException('طبيعة العمل أو استحقاق الإجازة');$names=array_column($doc['companies'],'B');if(!in_array($r['E']??'',$names,true)||(!empty($r['F'])&&!in_array($r['F'],$names,true)))throw new RuntimeException('شركة غير معروفة');foreach($dates[(int)$r['A']]??[]as $p)if($from<=($p[1]??'9999-12-31')&&($to??'9999-12-31')>=$p[0])throw new RuntimeException('فترات متداخلة');$dates[(int)$r['A']][]=[$from,$to];}catch(Throwable $e){$errors[]='فترة الموظف '.$r['A'].': '.$e->getMessage();}}
 return ['rows'=>$out,'errors'=>array_values(array_unique($errors)),'counts'=>['companies'=>count($doc['companies']),'employees'=>count($doc['people']),'periods'=>count($doc['periods'])]];
}
function setup_action(string $action,array $u,array $b):array {
 admin_only($u);$doc=prepared_data();$hash=hash('sha256',jencode($doc));$plan=setup_plan($doc);
 if($action==='setup_preview'){$_SESSION['setup_preview']=$hash;return $plan+['hash'=>$hash];}
 if($action!=='setup_commit')fail('عملية غير موجودة.',404);if(!hash_equals($_SESSION['setup_preview']??'',(string)($b['hash']??''))||!hash_equals($hash,(string)$b['hash']))fail('أعد المعاينة قبل الاستيراد.');if($plan['errors'])fail(implode('\n',$plan['errors']));
 db()->beginTransaction();query("SELECT setting_key FROM ep_settings WITH (UPDLOCK, HOLDLOCK) WHERE setting_key='prepared_import_v24'");$done=query("SELECT value_json FROM ep_settings WHERE setting_key='prepared_import_v24'")->fetchColumn();if($done){db()->commit();return ['already_imported'=>true,'mapping'=>json_decode($done,true)];}
 query('SELECT id FROM ep_users WITH (UPDLOCK, HOLDLOCK)');$plan=setup_plan($doc);if($plan['errors'])fail(implode('\n',$plan['errors']));$existingPeriods=[];foreach(query("SELECT user_id FROM ep_records WHERE module='service_period'")->fetchAll()as $p)$existingPeriods[(int)$p['user_id']]=true;
 $cm=[];foreach($doc['companies']as $r){$c=query('SELECT * FROM ep_companies WHERE name=?',[$r['B']])->fetch();if(!$c){$code=next_code('company');query('INSERT INTO ep_companies(code,name,legal_name,bank_name,bank_account,labor_file,active,created_at) VALUES(?,?,?,?,?,?,?,?)',[$code,$r['B'],$r['C']??'',str_replace('COMMERCAIL','COMMERCIAL',$r['D']??''),trim($r['E']??''),$r['F']??'',($r['G']??'')==='مفعلة'?1:0,utc_now()]);$c=company_by_code($code);}$cm[$r['B']]=$c['code'];}
 $map=[];$staff=[];usort($doc['people'],fn($a,$b)=>(int)$a['A']<=>(int)$b['A']);
 foreach($doc['people']as $r){$item=array_values(array_filter($plan['rows'],fn($p)=>$p['kind']==='employee'&&(int)$p['serial']===(int)$r['A']))[0];$id=$item['existing_id'];if($id){$record=query('SELECT * FROM ep_users WITH (UPDLOCK, HOLDLOCK) WHERE id=?',[$id])->fetch();$profile=decode($record['profile_json']);$profile=array_replace($profile,setup_profile($r));$profile['employee_code']=employee_key($record);query('UPDATE ep_users SET profile_json=? WHERE id=?',[jencode($profile),$id]);}
 else{$code=next_code('employee');$profile=setup_profile($r)+['employee_code'=>$code];query("INSERT INTO ep_users(username,password_hash,name,role,active,profile_json,created_at) VALUES(?,?,?,'employee',0,?,?)",[$code,password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),$r['B'],jencode($profile),utc_now()]);$id=(int)db()->lastInsertId();}
 $record=query('SELECT * FROM ep_users WHERE id=?',[$id])->fetch();$staff[(int)$r['A']]=$record;$map[]=['serial'=>(int)$r['A'],'name'=>$record['name'],'code'=>employee_key($record),'id'=>$id];}
 foreach($doc['periods']as $r){$record=$staff[(int)$r['A']];$uid=(int)$record['id'];$from=import_date($r['C']);$to=empty($r['D'])?null:import_date($r['D']);$note=$r['K']??'';$values=['company_code'=>$cm[$r['E']],'residence_company_code'=>empty($r['F'])?'':$cm[$r['F']],'department'=>$r['G']??'','job_title'=>$r['H']??'','staff_type'=>['شريك'=>'partner','مكتب'=>'office','مندوب'=>'rep','عن بُعد'=>'remote'][$r['I']],'attendance'=>!str_contains($note,'لا يخضع'),'leave'=>$r['J']==='نعم','payroll'=>!str_contains($note,'تحويل بنك فقط'),'bank'=>true,'note'=>$note];
 if(isset($existingPeriods[$uid]))fail('فترة خدمة موجودة؛ طابقها قبل استيراد الموظف '.$r['A']);
 query("INSERT INTO ep_records(module,user_id,title,date_from,date_to,status,body_json,created_at,updated_at) VALUES('service_period',?,?,?,?, 'approved',?,?,?)",[$uid,'فترة خدمة مستوردة',$from,$to,jencode($values),utc_now(),utc_now()]);$profile=array_replace(decode($record['profile_json']),['company_code'=>$values['company_code'],'residence_company_code'=>$values['residence_company_code'],'attendance_required'=>$values['attendance'],'leave_eligible'=>$values['leave'],'payroll_visible'=>$values['payroll'],'bank_visible'=>true]);$priorHire=$record['hired_on'];$earliest=$priorHire?min($priorHire,$from):$from;query('UPDATE ep_users SET hired_on=?,department=?,job_title=?,staff_type=?,profile_json=? WHERE id=?',[$earliest,$values['department'],$values['job_title'],$values['staff_type'],jencode($profile),$uid]);$staff[(int)$r['A']]=query('SELECT * FROM ep_users WHERE id=?',[$uid])->fetch();
 }
 query('INSERT INTO ep_settings(setting_key,value_json) VALUES(?,?)',['prepared_import_v24',jencode($map)]);audit('prepared_import','V24',['companies'=>count($cm),'employees'=>count($map),'hash'=>$hash]);db()->commit();unset($_SESSION['setup_preview']);return ['mapping'=>$map];
}
